solver = Solver()

# Inputs
inputs = [Int(f'in_{i}') for i in range(N)]
solver.add([And(inp >= 0, inp < num_inputs) for inp in inputs])

# States
states = [Int(f'state_{i}') for i in range(N + 1)]
solver.add([And(state >= 0, state < num_states) for state in states])

# Initial and final states
solver.add(states[0] == 0)
solver.add(states[N] == final_state)

# Only allow +1 transitions
for i in range(N):
    allowed_next = []
    for inp in range(num_inputs):
        if transitions[i][inp] == i + 1:
            allowed_next.append(inputs[i] == inp)
    # Only one input can advance +1
    solver.add(Or(*allowed_next))
    # Enforce next state
    solver.add(states[i + 1] == states[i] + 1)

# Optional: enforce counter constraints if you have them
counter_row = [23, 21, 32, 19, 17, 31, 38, 0]
unused_input = counter_row.index(0)
for i in range(N):
    solver.add(inputs[i] != unused_input)

