# Enumerate all solutions
solutions = []
while solver.check() == sat:
    model = solver.model()
    solution = [model[inp].as_long() for inp in inputs]
    solutions.append(solution)
    # print("Found", solution)
    l = 0
    inc = 0
    flag = ""
    for s in solution:
        s = int(s)
        if s <= l:
            flag += chr(inc)
            inc = 0
        inc += 1 << s
        l = s
    
    if "EPFL{" in flag and "}" in flag:
        print(flag)
        break
    print(flag)
        
    
    # Block this solution
    solver.add(Or([inp != val for inp, val in zip(inputs, solution)]))

print(f"Found {len(solutions)} solutions.")
# Optionally, print them all
for sol in solutions:
    print(sol)
